-- Per-org viewing link — one row per shareable per-unit URL generated by staff.
-- Token is duplicated in tena_master.viewing_link_registry(kind=1) so the public
-- surface can resolve org_id from the token without touching this DB first.

CREATE TABLE IF NOT EXISTS viewing_link (
  id           BIGINT       NOT NULL,
  token        VARCHAR(64)  NOT NULL,
  property_id  BIGINT       NOT NULL,
  unit_id      BIGINT       NOT NULL,
  employee_id  BIGINT       NOT NULL,
  created_by   BIGINT       NOT NULL,
  note         VARCHAR(500) DEFAULT NULL,
  status       TINYINT      NOT NULL DEFAULT 1,
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  revoked_at   TIMESTAMP    NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_vl_token (token),
  KEY idx_vl_unit (unit_id),
  KEY idx_vl_employee (employee_id),
  KEY idx_vl_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
